List.comp_traverse.code:
List.comp_traverse.{u, u_1} {F G : Type u → Type u} [Applicative F] [Applicative G] [LawfulApplicative G] {α : Type u_1}
  {β γ : Type u} (f : β → F γ) (g : α → G β) (x : List α) :
  List.traverse (Comp.mk ∘ (fun x => f <$> x) ∘ g) x = Comp.mk (List.traverse f <$> List.traverse g x)

Sum.map_traverse.code:
Sum.map_traverse.{u, u_1} {σ : Type u} {G : Type u → Type u} [Applicative G] [LawfulApplicative G] {α : Type u_1}
  {β γ : Type u} (g : α → G β) (f : β → γ) (x : σ ⊕ α) :
  (fun x => f <$> x) <$> Sum.traverse g x = Sum.traverse (fun x => f <$> g x) x

